import { writable } from 'svelte/store';
import { Game } from '../../../domain/game.js';
import { Sudoku } from '../../../domain/sudoku.js';

/**
 * 创建一个新的空棋盘
 */
function createEmptyGrid() {
  return Array.from({ length: 9 }, () => Array(9).fill(0));
}

/**
 * 把领域对象数据转换成 UI 可用的数据
 */
function createViewState(game) {
  const sudoku = game.getSudoku();
  const rawGrid = sudoku.getGrid();

  return {
    game,
    sudoku,

    grid: rawGrid.map(row => [...row]),

    candidates: game.getAllCandidates(),
    nextHints: game.getNextHints(),
    invalidCells: sudoku.getInvalidCells?.() || [],

    paused: false,
    won: game.isWon()
  };
}

/**
 * Store Adapter
 */
export function createGameStore() {
  const sudoku = new Sudoku(createEmptyGrid());
  const game = new Game(sudoku);

  const { subscribe, set, update } = writable(createViewState(game));

  return {
    subscribe,

    /** 新游戏 */
    newGame: (initialGrid = null) => {
      	game.newGame(initialGrid || createEmptyGrid());
      	set(createViewState(game));
    },

    /** 填写 */
    guess: ({ row, col, value }) => {
		console.log("guess called:", row, col, value);
      	game.guess({ row, col, value });
      	set(createViewState(game));
    },

    /** 撤销 */
    undo: () => {
      	game.undo();
      	set(createViewState(game));
    },

    /** 重做 */
    redo: () => {
      	game.redo();
      	set(createViewState(game));
    },

    /** 提示 */
    hint: (pos) => {
      	if (!pos || pos.x === null || pos.y === null) return { success: false, message: 'Invalid position' };
      	
      	const hint = game.getHint(pos.y, pos.x);
      	let success = false;
      	let message = '';
      	
      	// 如果当前格子有唯一候选，填入答案
      	if (hint.candidates.length === 1) {
      		const initialGrid = game.getInitialSudoku().getGrid();
      		if (initialGrid[pos.y][pos.x] === 0) {
      			game.guess({ row: pos.y, col: pos.x, value: hint.candidates[0] });
      			success = true;
      			message = `Filled current cell: ${hint.candidates[0]}`;
      		} else {
      			message = 'Current cell is already filled';
      		}
      	} else if (hint.nextHints.length > 0) {
      		// 如果有下一步提示，填入第一个提示的答案
      		const next = hint.nextHints[0];
      		const initialGrid = game.getInitialSudoku().getGrid();
      		if (initialGrid[next.row][next.col] === 0) {
      			game.guess({ row: next.row, col: next.col, value: next.value });
      			success = true;
      			message = `Filled (${next.row + 1}, ${next.col + 1}): ${next.value}`;
      		} else {
      			message = 'Next hint cell is already filled';
      		}
      	} else if (hint.candidates.length === 0) {
      		message = 'No candidates available';
      	} else {
      		message = 'Multiple candidates, no unique solution';
      	}
      	
      	set(createViewState(game));
      	return { success, message, hint };
    },

    /** 暂停 */
    pause: () => update(s => ({ ...s, paused: true })),

    /** 恢复 */
    resume: () => update(s => ({ ...s, paused: false })),
  };
}

export const gameStore = createGameStore();